fn ap(args: &[A], i: usize) -> usize {
    match args[i] {
        A::P(p) => p,
        A::S(p) => p as usize,
        A::M(p, _) => p,
        A::O(p) => p,
        A::I(v) => v as usize,
        _ => 0,
    }
}


